static __forceinline PathfindCell *rva003eb1f0CellAt(
	Pathfinder *self, PathfindLayerEnum layer, Int x, Int y)
{
	PathfindCell *cell;
	if (x < self->m_extentLoX || x > self->m_extentHiX ||
		y < self->m_extentLoY || y > self->m_extentHiY)
		return 0;
	if (layer > 1 && layer <= 15)
	{
		cell = self->m_layers[layer].getCell(x, y);
		if (cell != 0)
			return cell;
	}
	return self->m_map[x] + y;
}

void Pathfinder::adjustCoordToCell(
	Int x, Int y, Bool center, Coord3D &position, PathfindLayerEnum layer)
{
	if (center)
	{
		position.x = ((Real)x + Rva003EB1F0K1253) *
			Rva003EB1F0DirectionWeight;
		position.y = ((Real)y + Rva003EB1F0K1253) *
			Rva003EB1F0DirectionWeight;
	}
	else
	{
		position.x = ((Real)x + Rva003EB1F0CellBias) * Rva003EB1F0CellScale;
		position.y = ((Real)y + Rva003EB1F0CellBias) * Rva003EB1F0CellScale;
	}
	Real groundHeight = Rva003EB1F0Terrain->getLayerHeight(
		position.x, position.y, (Int)layer, 0, 1);
	position.z = groundHeight;
}

void Pathfinder::snapClosestGoalPosition(Object *obj,
	Coord3D *pos)
{
	Int iRadius;
	Bool center;
	if (Rva003EB1F0DebugFlag && Rva003EB1F0DebugSink)
		bfmeRetailCritterDesyncLog(Rva003EB1F0DebugSink,
			"CritterDesync: Pathfinder::SnapClosestGoalPosition() called with pos=%g,%g,%g", pos->x, pos->y, pos->z);

	getRadiusAndCenter(obj, iRadius, center);
	if (Rva003EB1F0DebugFlag && Rva003EB1F0DebugSink)
	{
		const char *centerName = center ? "TRUE" :
			"FALSE";
		bfmeRetailCritterDesyncLog(Rva003EB1F0DebugSink,
			"CritterDesync: Pathfinder::SnapClosestGoalPosition() iRadius=%d, center=%s", iRadius, centerName);
	}

	ICoord2D cell;
	Coord3D adjustDest = *pos;
	PathfindLayerEnum layer;

	if (!center)
	{
		if (Rva003EB1F0DebugFlag && Rva003EB1F0DebugSink)
			bfmeRetailCritterDesyncLog(Rva003EB1F0DebugSink,
				"CritterDesync: Pathfinder::SnapClosestGoalPosition() !center, adjustDest...");
		adjustDest.x += Rva003EB1F0K1266C;
		adjustDest.y += Rva003EB1F0K1266C;
	}

	layer = Rva003EB1F0Terrain->getLayerForDestination(obj, pos);
	worldToCell(&adjustDest, &cell);
	adjustCoordToCell(cell.x, cell.y,
		center, *pos,
		LAYER_GROUND);

	if (Rva003EB1F0DebugFlag && Rva003EB1F0DebugSink)
	{
		const char *centerName = center ? "TRUE" :
			"FALSE";
		bfmeRetailCritterDesyncLog(Rva003EB1F0DebugSink,
			"CritterDesync: Pathfinder::SnapClosestGoalPosition() CheckDestination about to get called with cell=%d,%d, layer=%d, iRadius=%d, center=%s, pos=%g%g%g", cell.x, cell.y,
			(Int)layer, iRadius, centerName, pos->x, pos->y, pos->z);
	}

	Bool initialCheck = checkUnoccupied(obj,
		cell.x, cell.y, layer, iRadius, center);
	if (initialCheck)
	{
		Bool initialEmpty = initialCheck;
		if (initialEmpty)
		{
			if (Rva003EB1F0DebugFlag && Rva003EB1F0DebugSink)
				bfmeRetailCritterDesyncLog(Rva003EB1F0DebugSink,
					"CritterDesync: Pathfinder::SnapClosestGoalPosition() CheckDestination succeeds, returning...");
			return;
		}
	}

	if (Rva003EB1F0DebugFlag && Rva003EB1F0DebugSink)
		bfmeRetailCritterDesyncLog(Rva003EB1F0DebugSink,
			"CritterDesync: Pathfinder::SnapClosestGoalPosition() CheckDestination fails, continuing...");

	Int i;
	Int j;
	for (i = cell.x - 1; i < cell.x + 2; ++i)
	{
		for (j = cell.y - 1; j < cell.y + 2; ++j)
		{
			Bool neighbourCheck = checkUnoccupied(obj,
				i, j, layer, iRadius, center);
			if (neighbourCheck)
			{
				Bool neighbourEmpty = neighbourCheck;
				if (neighbourEmpty)
				{
					adjustCoordToCell(i, j, center, *pos, layer);
					if (Rva003EB1F0DebugFlag && Rva003EB1F0DebugSink)
					{
						const char *centerName = center ?
							"TRUE" :
							"FALSE";
						bfmeRetailCritterDesyncLog(
							Rva003EB1F0DebugSink,
							"CritterDesync: Pathfinder::SnapClosestGoalPosition() CheckDestination2 succeeds with cell=%d,%d, layer=%d, iRadius=%d, center=%s, pos=%g%g%g", cell.x, cell.y, (Int)layer,
						 iRadius, centerName, pos->x, pos->y, pos->z);
					}
					return;
				}
			}
		}
	}

	if (iRadius == 0)
	{
		for (i = cell.x - 1; i < cell.x + 2; ++i)
		{
			for (j = cell.y - 1; j < cell.y + 2; ++j)
			{
				PathfindCell *newCell =
					rva003eb1f0CellAt(this, layer, i, j);
				if (newCell != 0)
				{
					void *info = newCell->m_info;
					Int goal = info == 0 ? 0 :
						*(Int *)((char *)info + 0x14);
					if (goal == 0 || goal == obj->m_id)
					{
						adjustCoordToCell(i, j, center, *pos, layer);
						if (Rva003EB1F0DebugFlag &&
							Rva003EB1F0DebugSink)
						{
							const char *centerName = center ?
								"TRUE" :
								"FALSE";
							bfmeRetailCritterDesyncLog(
								Rva003EB1F0DebugSink,
								"CritterDesync: Pathfinder::SnapClosestGoalPosition() CheckDestination3 succeeds with cell=%d,%d, layer=%d, iRadius=%d, center=%s, pos=%g%g%g", i, j,
								(Int)layer, iRadius, centerName,
								pos->x, pos->y, pos->z);
						}
						return;
					}
				}
			}
		}

		for (i = cell.x - 1; i < cell.x + 2; ++i)
		{
			for (j = cell.y - 1; j < cell.y + 2; ++j)
			{
				PathfindCell *newCell =
					rva003eb1f0CellAt(this, layer, i, j);
				if (newCell != 0 &&
					(UByte)(newCell->m_packed & 0x38) != 0x18)
				{
				adjustCoordToCell(i, j, center, *pos, layer);
					if (Rva003EB1F0DebugFlag &&
						Rva003EB1F0DebugSink)
					{
						const char *centerName = center ?
							"TRUE" :
							"FALSE";
						bfmeRetailCritterDesyncLog(
							Rva003EB1F0DebugSink,
							"CritterDesync: Pathfinder::SnapClosestGoalPosition() CheckDestination4 succeeds with cell=%d,%d, layer=%d, iRadius=%d, center=%s, pos=%g%g%g", i, j,
							(Int)layer, iRadius, centerName,
								pos->x, pos->y, pos->z);
					}
					return;
				}
			}
		}
	}

	if (Rva003EB1F0DebugFlag && Rva003EB1F0DebugSink)
	bfmeRetailCritterDesyncLog(Rva003EB1F0DebugSink,
			"CritterDesync: Pathfinder::SnapClosestGoalPosition() iRadius=%d>0 do nothing case, pos=%g%g%g", iRadius, pos->x, pos->y, pos->z);
}
